     * 先播开场背景音效（intro），再播语音提示（voice）——避免"突然有人
     * 说话"。两文件格式可不同，tone_play_one 各自独立 open/hw_params。 */
    char *copy = (char *)arg;
    char *intro = copy;
    char *voice = strchr(copy, '|');

    if (voice)
    {
        *voice = '\0';
        voice++;
    }
    if (intro[0])
        tone_play_one(intro);
    if (voice && voice[0])
