/****************************************************************************
 * apps/vendor/allwinnertech/apps/tone_test/tone_test_main.c
 *
 * 2026-09-01 P142：NSH 自测命令（P142 背景音乐开场音效配套）。
 *   tone_test boot   —— 开机欢迎：bg_reward_heart（心之容器）+ greet_morning
 *   tone_test water  —— 喝水提醒：bg_reward_std（标准）+ popup_water_1
 *   tone_test sit    —— 久坐提醒：bg_reward_std（标准）+ popup_sit_1
 *   tone_test lux    —— 喝满 6 次水夸奖：bg_reward_lux（豪华）+ care_01
 *   tone_test all    —— 依次播放以上 4 组（每组间隔 6s，便于听辨）
 *
 * 通过 luncher_dm 的 dm_tone_play_seq() 播放（同镜像符号共享，见
 * uartdbg_test 先例）。不触发真实状态机，仅试听"背景音乐+语音"组合。
 *
 * Licensed to the Apache Software Foundation (ASF) under one or more
 * contributor license agreements.
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <string.h>
#include <unistd.h>

/* dm_tone_play_seq 定义在 luncher_dm（deskmate_ui.c），跨 app 直接调用 */
extern void dm_tone_play_seq(const char *intro, const char *voice);

/* 每组间隔（秒）：背景音乐 2~5s + 语音 1~3s，6s 足够播完再播下一组 */
#define TONE_TEST_GAP_S 6

typedef struct
{
  const char *label;
  const char *intro;    /* 背景音乐 wav（/resource/tones/） */
  const char *voice;    /* 语音提示 wav */
} tone_scene_t;

static const tone_scene_t g_scenes[] =
{
  { "boot",  "bg_reward_heart", "greet_morning"  },  /* 开机欢迎：心之容器 */
  { "water", "bg_reward_std",   "popup_water_1"  },  /* 喝水提醒：标准 */
  { "sit",   "bg_reward_std",   "popup_sit_1"    },  /* 久坐提醒：标准 */
  { "lux",   "bg_reward_lux",   "care_01"        },  /* 喝满6次夸奖：豪华 */
};

static void play_scene(const tone_scene_t *s)
{
  printf("[tone_test] %s: intro=%s voice=%s\n", s->label, s->intro, s->voice);
  dm_tone_play_seq(s->intro, s->voice);
}

int main(int argc, char *argv[])
{
  if (argc < 2)
    {
      printf("usage: tone_test <boot|water|sit|lux|all>\n");
      return -1;
    }

  if (strcmp(argv[1], "all") == 0)
    {
      for (size_t i = 0; i < sizeof(g_scenes) / sizeof(g_scenes[0]); i++)
        {
          play_scene(&g_scenes[i]);
          if (i + 1 < sizeof(g_scenes) / sizeof(g_scenes[0]))
            sleep(TONE_TEST_GAP_S);
        }
      printf("[tone_test] all 4 scenes played\n");
      return 0;
    }

  for (size_t i = 0; i < sizeof(g_scenes) / sizeof(g_scenes[0]); i++)
    {
      if (strcmp(argv[1], g_scenes[i].label) == 0)
        {
          play_scene(&g_scenes[i]);
          return 0;
        }
    }

  printf("tone_test: unknown scene '%s' (boot|water|sit|lux|all)\n", argv[1]);
  return -1;
}

